-- 0221 — Academy, niveau 1 : leçons 1 à 4 réécrites (2026-11-13).
--
-- Les versions précédentes affichaient comme « données réelles, Source BRVM »
-- des cours faux (8 sur 8 au 17/07/2026), un dividende Sonatel faux, et trois
-- cas présentés comme réels qui étaient inventés (M. Konaté, M. Diallo,
-- Mme Ouédraogo). Elles passent au format des leçons 5 à 11 : chiffres de
-- marché lus en base au chargement (blocs donnees_reelles), exemples annoncés
-- comme pédagogiques, AMF-UMOA, 5 questions, avertissement.
-- Source : frontend/lib/academy/contenus/lecon{1..4}-*.json (testés).
-- Sauvegarde du cours avant écriture : docs/academy/sauvegardes/2026-11-13-academy-niveau-1-initiation.json
-- Aucune donnée personnelle.

update public.academy_courses
   set content = jsonb_set(content, '{lessons,0}', ((content->'lessons'->0)) || $wb${"titre":"Leçon 1 — Qu’est-ce que la BRVM et comment ça marche ?","categorie":"general","duree_min":9,"sous_titre":"Une bourse commune à huit pays, des sociétés que vous connaissez, et un prix qui se forme chaque jour.","resume":"La BRVM est la bourse commune aux huit pays de l’UEMOA.\nCette leçon explique ce qu’on y achète, comment le prix d’une action se forme, ce que mesurent les indices et les réflexes à prendre avant d’y placer le moindre franc.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Une bourse commune à huit pays","contenu":"La Bourse Régionale des Valeurs Mobilières (BRVM), installée à Abidjan, fonctionne depuis 1998. C’est un marché unique pour les huit pays de l’UEMOA : Bénin, Burkina Faso, Côte d’Ivoire, Guinée-Bissau, Mali, Niger, Sénégal et Togo.\nOn y échange des actions et des obligations, en francs CFA. Le marché est supervisé par l’Autorité des Marchés Financiers de l’UMOA (AMF-UMOA).","flux":[{"titre":"Une entreprise","detail":"Elle ouvre son capital pour se financer.","icone":"entreprise"},{"titre":"Des actions","detail":"Son capital est découpé en parts cotées à la BRVM.","icone":"piece"},{"titre":"Des investisseurs","detail":"Ils achètent ces parts et deviennent actionnaires.","icone":"actionnaires"}]},{"type":"importance","titre":"Acheter une action, c’est devenir copropriétaire","contenu":"Une action est une fraction du capital d’une entreprise réelle. En la détenant, vous acquérez des droits, mais aucune garantie.","points":[{"titre":"Une part des bénéfices, si l’assemblée la distribue","detail":"Le dividende est voté chaque année par l’assemblée générale. Il peut monter, baisser ou disparaître.","verifier":"l’historique des dividendes de la société sur plusieurs exercices."},{"titre":"Une voix en assemblée générale","detail":"Les actionnaires votent sur les comptes, la distribution du bénéfice et la nomination des administrateurs."},{"titre":"La possibilité de revendre","detail":"Vous pouvez revendre vos titres par votre SGI. Le prix n’est pas garanti, et sur une valeur peu échangée, trouver un acheteur peut prendre du temps.","verifier":"les volumes échangés de la valeur avant d’acheter."}]},{"type":"definition","titre":"Comment se forme le prix d’une action","contenu":"Le prix naît de la rencontre des ordres d’achat et de vente transmis par les SGI. Quand les acheteurs sont plus pressés que les vendeurs, le cours monte ; dans le cas inverse, il baisse.\nLa variation d’un titre sur une séance est encadrée par les règles du marché. Le cours de clôture de chaque valeur est publié chaque jour dans le Bulletin officiel de la cote.","etapes":[{"titre":"Les ordres arrivent","detail":"Votre SGI transmet votre ordre au système de cotation de la BRVM."},{"titre":"Ils se rencontrent","detail":"Un ordre d’achat s’exécute face à un ordre de vente compatible en prix.","cle":true},{"titre":"Le cours est publié","detail":"Dernier prix échangé, volumes et variations, dans le Bulletin officiel de la cote."},{"titre":"Les titres sont livrés","detail":"Le Dépositaire central (DC/BR) inscrit les titres sur votre compte et règle les espèces."}],"etapes_style":"frise"},{"type":"cas","reel":true,"titre":"Les indices, thermomètre du marché","contenu":"Un indice résume en un chiffre l’évolution d’un ensemble d’actions. Le BRVM Composite suit toutes les actions cotées ; le BRVM 30 suit trente des valeurs les plus échangées.\nCes indices sont calculés sur les cours : les dividendes n’y entrent pas. Une année où l’indice stagne peut donc avoir rapporté de l’argent aux actionnaires qui ont touché leurs dividendes.","donnees_reelles":{"vue":"indices","codes":["BRVMC","BRVM30"]}},{"type":"cas","reel":true,"titre":"Des sociétés que vous connaissez","contenu":"On trouve à la BRVM des banques, des opérateurs de télécommunications, des distributeurs d’énergie, des industriels et des groupes agricoles, souvent présents dans votre quotidien.\nLe tableau donne le dernier cours de six d’entre elles. Le prix d’une action ne dit rien de sa qualité : il dépend surtout du nombre de titres en circulation.","donnees_reelles":{"vue":"cours","codes":["SNTS","ORAC","SGBC","CIEC","TTLC","SPHC"]}},{"type":"piege","titre":"Quatre erreurs de débutant","contenu":"Ces erreurs coûtent plus cher que n’importe quel mauvais choix de valeur.","points":[{"titre":"Chercher un gain rapide","detail":"La bourse récompense surtout la patience. Un horizon de plusieurs années laisse le temps aux dividendes et à la croissance des sociétés de travailler."},{"titre":"Placer de l’argent dont on aura besoin","detail":"Loyer, scolarité, urgence médicale : cet argent ne va pas en actions. Constituez d’abord une épargne de précaution."},{"titre":"Vendre sans regarder le calendrier","detail":"Vendre avant la date de détachement fait perdre le dividende de l’année.","verifier":"le calendrier des dividendes de vos valeurs."},{"titre":"Passer par un intermédiaire non agréé","detail":"Seules les SGI agréées peuvent acheter des actions pour vous à la BRVM.","verifier":"la liste des SGI agréées publiée par l’AMF-UMOA."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Cinq idées à garder en tête.","points":[{"titre":"Un marché unique pour huit pays","detail":"La BRVM sert toute l’UEMOA, sous la supervision de l’AMF-UMOA."},{"titre":"Une action est une part d’entreprise","detail":"Elle donne droit au dividende voté, au vote en assemblée et à la revente."},{"titre":"Le prix vient de l’offre et de la demande","detail":"Il change à chaque séance, dans des limites fixées par le marché."},{"titre":"Les indices mesurent les cours, pas les dividendes","detail":"Le BRVM Composite suit toutes les actions, le BRVM 30 trente des plus échangées."},{"titre":"Tout passe par une SGI agréée","detail":"C’est votre intermédiaire obligatoire et votre premier interlocuteur."}]}],"chart":null,"charts":[],"quiz":[{"question":"Combien de pays partagent la BRVM ?","options":["Trois","Cinq","Huit","Quinze"],"correct":2,"explication":"La BRVM est commune aux huit pays de l’UEMOA : Bénin, Burkina Faso, Côte d’Ivoire, Guinée-Bissau, Mali, Niger, Sénégal et Togo."},{"question":"Qui supervise le marché financier régional ?","options":["La BRVM elle-même","L’AMF-UMOA","Chaque SGI pour ses clients","Le ministère des Finances de chaque pays"],"correct":1,"explication":"L’Autorité des Marchés Financiers de l’UMOA agrée les intermédiaires, contrôle le marché et protège les investisseurs. La BRVM, elle, organise les séances."},{"question":"Pour acheter une action cotée à la BRVM, par qui faut-il passer ?","options":["Directement par la BRVM","Par une SGI agréée","Par n’importe quelle banque","Par la société émettrice"],"correct":1,"explication":"Un particulier ne peut pas passer d’ordre directement : il passe par une Société de Gestion et d’Intermédiation agréée, qui transmet l’ordre et conserve les titres."},{"question":"Le BRVM Composite progresse de 0 % sur une année. Les actionnaires ont-ils forcément gagné 0 % ?","options":["Oui, l’indice dit tout","Non : l’indice ne compte pas les dividendes versés","Non : l’indice ne compte que les banques","Oui, sauf pour les obligations"],"correct":1,"explication":"L’indice est calculé sur les seuls cours. Un actionnaire qui a touché ses dividendes a pu gagner de l’argent même si l’indice n’a pas bougé."},{"question":"Lequel de ces droits une action ne donne-t-elle PAS ?","options":["Voter en assemblée générale","Percevoir le dividende voté","Revendre ses titres","Un revenu garanti chaque année"],"correct":3,"explication":"Le dividende est voté chaque année : il n’est jamais garanti. Une action comporte un risque de perte en capital."}],"qcm":{"question":"Combien de pays partagent la BRVM ?","options":["Trois","Cinq","Huit","Quinze"],"correct":2,"explication":"La BRVM est commune aux huit pays de l’UEMOA : Bénin, Burkina Faso, Côte d’Ivoire, Guinée-Bissau, Mali, Niger, Sénégal et Togo."},"liens":[{"label":"Les indices et la séance du jour","href":"/dashboard"},{"label":"Les cours de toutes les actions","href":"/actions"},{"label":"Comparer les SGI agréées","href":"/comparateur-sgi"}]}$wb$::jsonb),
       updated_at = now()
 where slug = 'academy-niveau-1-initiation'
   and content->'lessons'->0->>'titre' = $wb$Qu’est-ce que la BRVM et comment ça marche ?$wb$;

update public.academy_courses
   set content = jsonb_set(content, '{lessons,1}', ((content->'lessons'->1)) || $wb${"titre":"Leçon 2 — Les 4 acteurs clés du marché","categorie":"regulatory","duree_min":8,"sous_titre":"Qui organise, qui contrôle, qui exécute, qui conserve : et à qui s’adresser en cas de problème.","resume":"Quatre acteurs font fonctionner la BRVM : la bourse, le régulateur, votre SGI et le dépositaire central.\nBien distinguer leurs rôles vous fait gagner du temps quand un problème survient, et vous protège des escroqueries.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Quatre acteurs, quatre rôles","contenu":"Chaque acteur a une mission précise. Les confondre, c’est frapper à la mauvaise porte, ou faire confiance à qui n’en mérite pas.","tableau":{"colonnes":["Acteur","Son rôle","Ce qu’il fait pour vous"],"lignes":[["BRVM","La bourse","Organise les séances, publie les cours et les indices, tient le Bulletin officiel de la cote."],["AMF-UMOA","Le régulateur","Agrée les intermédiaires, contrôle le marché, protège les investisseurs et sanctionne les abus."],["SGI","Votre intermédiaire","Ouvre votre compte, exécute vos ordres, conserve vos titres et vous adresse vos relevés."],["DC/BR","Le dépositaire central","Tient le registre des titres et règle les échanges entre intermédiaires."]],"note":"L’AMF-UMOA a succédé au CREPMF : les documents anciens emploient encore ce nom."}},{"type":"importance","titre":"De votre ordre à vos titres","contenu":"Chaque achat suit la même chaîne. Vous ne parlez qu’à votre SGI ; les autres acteurs travaillent derrière elle.","flux":[{"titre":"Vous","detail":"Vous passez votre ordre à votre SGI.","icone":"decision"},{"titre":"Votre SGI","detail":"Elle le transmet au système de cotation.","icone":"entreprise"},{"titre":"La BRVM","detail":"L’ordre rencontre un vendeur en séance.","icone":"graphique"},{"titre":"Le DC/BR","detail":"Les titres et les espèces changent de main.","icone":"paiement"}]},{"type":"cas","titre":"Un dividende qui n’arrive pas : par où commencer","contenu":"Situation pédagogique : la date de paiement d’un dividende est passée, et rien n’apparaît sur votre compte.\nLe bon ordre des démarches évite de perdre des jours.","etapes":[{"titre":"Vérifier la date de paiement","detail":"Elle figure au calendrier des dividendes publié par la BRVM."},{"titre":"Lire son relevé","detail":"Le dividende est versé sur le compte espèces associé au compte-titres."},{"titre":"Contacter sa SGI","detail":"C’est elle qui tient votre compte : c’est le bon premier interlocuteur.","cle":true},{"titre":"Faire une réclamation écrite","detail":"Si la réponse ne vient pas, une réclamation écrite à la SGI laisse une trace."},{"titre":"En dernier recours, le régulateur","detail":"L’AMF-UMOA veille au respect des règles par les intermédiaires agréés."}]},{"type":"piege","titre":"Reconnaître une fausse « opportunité »","contenu":"Des escrocs se présentent comme des courtiers ou des « experts » sur les réseaux sociaux et les messageries. Quatre signaux doivent vous arrêter.","points":[{"titre":"Un gain promis, garanti ou très élevé","detail":"Aucun placement en actions ne garantit un rendement. Une promesse de gain sûr est un mensonge."},{"titre":"La pression pour décider vite","detail":"« Plus que quelques places », « l’offre expire ce soir » : une vraie SGI vous laisse le temps de lire."},{"titre":"Un agrément introuvable","detail":"Seuls les intermédiaires agréés peuvent recevoir vos ordres.","verifier":"le nom exact sur la liste officielle de l’AMF-UMOA."},{"titre":"Des fonds versés à une personne","detail":"Les versements se font sur le compte de la SGI, jamais sur le compte personnel d’un conseiller."}]},{"type":"lexique","titre":"Le vocabulaire de l’écosystème","contenu":"Six mots que vous retrouverez dans tous les documents de votre SGI.","points":[{"titre":"BRVM","detail":"Bourse Régionale des Valeurs Mobilières : la bourse commune aux huit pays de l’UEMOA."},{"titre":"AMF-UMOA","detail":"Autorité des Marchés Financiers de l’UMOA : le régulateur, qui a succédé au CREPMF."},{"titre":"SGI","detail":"Société de Gestion et d’Intermédiation : l’intermédiaire agréé par lequel il faut passer."},{"titre":"DC/BR","detail":"Dépositaire Central / Banque de Règlement : il tient le registre des titres et règle les échanges."},{"titre":"Compte-titres","detail":"Le compte, tenu par votre SGI, où sont inscrites vos actions, avec un compte espèces associé."},{"titre":"Règlement-livraison","detail":"L’échange des titres contre les espèces, quelques jours après l’exécution de l’ordre."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Quatre idées à garder en tête.","points":[{"titre":"La BRVM organise","detail":"Séances, cours, indices, Bulletin officiel de la cote."},{"titre":"L’AMF-UMOA régule","detail":"Elle agrée les intermédiaires et protège les investisseurs."},{"titre":"Votre SGI exécute et conserve","detail":"C’est votre premier interlocuteur pour tout problème."},{"titre":"Vérifiez toujours l’agrément","detail":"Avant d’ouvrir un compte ou de verser le moindre franc."}]}],"chart":null,"charts":[],"quiz":[{"question":"Votre dividende n’est pas arrivé à la date de paiement. Qui contactez-vous en premier ?","options":["La BRVM","L’AMF-UMOA","Votre SGI","La société qui verse le dividende"],"correct":2,"explication":"Votre SGI tient votre compte-titres et votre compte espèces : elle seule peut vérifier ce qui s’est passé sur votre compte. Le régulateur n’intervient qu’en dernier recours."},{"question":"Quel acteur agrée les SGI et contrôle le marché ?","options":["La BRVM","L’AMF-UMOA","Le DC/BR","La BCEAO"],"correct":1,"explication":"L’Autorité des Marchés Financiers de l’UMOA, qui a succédé au CREPMF, agrée les intermédiaires et veille au respect des règles."},{"question":"Quel est le rôle du DC/BR ?","options":["Fixer le prix des actions","Tenir le registre des titres et régler les échanges","Conseiller les investisseurs","Organiser les assemblées générales"],"correct":1,"explication":"Le Dépositaire Central / Banque de Règlement inscrit les titres et règle les espèces entre intermédiaires après chaque échange."},{"question":"Un « conseiller » vous propose sur WhatsApp un placement garanti à 15 % par mois. Que faites-vous ?","options":["Vous versez une petite somme pour tester","Vous refusez : aucun placement en actions n’est garanti","Vous demandez une remise","Vous attendez que l’offre expire pour décider"],"correct":1,"explication":"Un gain garanti et très élevé est le signe le plus sûr d’une escroquerie. Vérifiez aussi l’agrément sur la liste de l’AMF-UMOA."},{"question":"Où sont inscrites les actions que vous achetez ?","options":["Sur votre compte-titres, tenu par votre SGI","Sur un certificat papier envoyé chez vous","Sur le site de la société","Sur votre compte bancaire courant"],"correct":0,"explication":"Les titres sont dématérialisés : ils sont inscrits sur votre compte-titres chez votre SGI, et enregistrés au dépositaire central."}],"qcm":{"question":"Votre dividende n’est pas arrivé à la date de paiement. Qui contactez-vous en premier ?","options":["La BRVM","L’AMF-UMOA","Votre SGI","La société qui verse le dividende"],"correct":2,"explication":"Votre SGI tient votre compte-titres et votre compte espèces : elle seule peut vérifier ce qui s’est passé sur votre compte. Le régulateur n’intervient qu’en dernier recours."},"liens":[{"label":"Comparer les SGI agréées","href":"/comparateur-sgi"},{"label":"Le calendrier des dividendes","href":"/dividendes/calendrier"},{"label":"Le guide du débutant","href":"/debutant"}]}$wb$::jsonb),
       updated_at = now()
 where slug = 'academy-niveau-1-initiation'
   and content->'lessons'->1->>'titre' = $wb$Les 4 acteurs clés du marché$wb$;

update public.academy_courses
   set content = jsonb_set(content, '{lessons,2}', ((content->'lessons'->2)) || $wb${"titre":"Leçon 3 — Combien faut-il pour investir à la BRVM ?","categorie":"evaluation","duree_min":9,"sous_titre":"Le vrai ticket d’entrée : le cours d’une action, les frais, et ce qu’il faut pour répartir son risque.","resume":"Aucun montant minimum n’est fixé par la loi pour acheter une action : on achète des titres entiers, au cours du jour.\nCette leçon montre ce que coûte réellement un premier achat, pourquoi les frais pèsent lourd sur les petits ordres, et comment répartir un premier budget.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Le prix d’une action n’est pas un droit d’entrée","contenu":"À la BRVM, on achète des actions entières, au cours de la séance. Le coût d’un achat est donc le cours multiplié par la quantité, auquel s’ajoutent les frais.\nCertaines SGI demandent un dépôt minimum à l’ouverture du compte : il varie d’une SGI à l’autre, et se compare avant de s’engager.","formules":[{"nom":"Coût d’un achat","expression":"Quantité × Cours + Frais","exemple":"10 × 2 500 + 1 % de frais = 25 250 FCFA"}]},{"type":"cas","reel":true,"titre":"Sur la BRVM : le prix de 10 actions","contenu":"Le tableau donne le dernier cours de six valeurs, et ce que coûtent 10 actions de chacune, hors frais.\nL’écart entre elles vient surtout du nombre de titres de chaque société, pas de leur qualité : une action à petit prix n’est pas une bonne affaire pour autant.","donnees_reelles":{"vue":"cours","codes":["UNXC","TTLC","CIEC","SPHC","SGBC","SNTS"],"actions":10}},{"type":"importance","titre":"Les frais, l’ennemi des petits ordres","contenu":"Chaque ordre supporte des frais : le courtage de la SGI, des commissions du marché et du dépositaire, et la TVA sur ces commissions. Beaucoup de SGI appliquent aussi un montant minimum par ordre.\nCes frais se paient à l’achat puis à la revente. L’action doit donc monter d’au moins le total des deux pour que l’opération soit gagnante.","formules":[{"nom":"Seuil de rentabilité d’un aller-retour","expression":"Frais à l’achat + Frais à la revente","exemple":"1,5 % + 1,5 % : l’action doit monter d’environ 3 %"}],"points":[{"titre":"Le courtage","detail":"La rémunération de la SGI, en pourcentage de l’ordre, souvent avec un minimum.","verifier":"la grille tarifaire de votre SGI."},{"titre":"Les commissions de marché","detail":"Celles de la bourse et du dépositaire central, communes à toutes les SGI."},{"titre":"La tenue de compte","detail":"Certaines SGI facturent des frais annuels de tenue de compte ou de conservation."}]},{"type":"cas","titre":"Répartir un premier budget de 50 000 FCFA","contenu":"Exemple pédagogique : avec 50 000 FCFA, on peut viser trois valeurs de trois secteurs différents, soit un peu plus de 16 000 FCFA par ligne, frais compris.\nLe nombre d’actions de chaque ligne dépend de son cours : quelques titres d’une valeur chère, davantage d’une valeur moins chère. L’important est la répartition, pas le nombre de titres.","formules":[{"nom":"Budget par ligne","expression":"Budget total ÷ Nombre de valeurs","exemple":"50 000 ÷ 3 ≈ 16 667 FCFA par valeur"}]},{"type":"piege","titre":"Ne pas mettre tous ses œufs dans le même panier","contenu":"Exemple pédagogique : 50 000 FCFA sur une seule action qui baisse de 20 %, c’est 10 000 FCFA de perte. Répartis sur cinq valeurs à parts égales, la même baisse sur une seule d’entre elles coûte 2 000 FCFA, soit 4 % du portefeuille.","points":[{"titre":"Tout miser sur une valeur","detail":"Une mauvaise nouvelle sur une société, et c’est tout le capital qui recule."},{"titre":"Multiplier les très petits ordres","detail":"Avec un minimum de frais par ordre, dix petits achats coûtent bien plus qu’un seul."},{"titre":"Investir son épargne de précaution","detail":"L’argent des imprévus doit rester disponible : une action peut être en baisse le jour où vous en avez besoin."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Quatre idées à garder en tête.","points":[{"titre":"Coût = quantité × cours + frais","detail":"Aucun minimum légal ; le dépôt minimum dépend de la SGI."},{"titre":"Les frais se paient deux fois","detail":"À l’achat et à la revente : ils fixent le seuil de rentabilité."},{"titre":"Un cours bas n’est pas une affaire","detail":"Il dépend du nombre de titres de la société."},{"titre":"Répartir dès le premier budget","detail":"Au moins trois valeurs, dans des secteurs différents."}]}],"chart":null,"charts":[],"quiz":[{"question":"Une action cote 2 500 FCFA. Vous en achetez 10, avec 1 % de frais. Combien payez-vous ?","options":["2 525 FCFA","25 000 FCFA","25 250 FCFA","27 500 FCFA"],"correct":2,"explication":"10 × 2 500 = 25 000 FCFA, plus 1 % de frais, soit 250 FCFA : 25 250 FCFA au total."},{"question":"Vos frais sont de 1,5 % à l’achat et 1,5 % à la revente. De combien l’action doit-elle monter, environ, pour que l’opération ne perde rien ?","options":["0,75 %","1,5 %","3 %","15 %"],"correct":2,"explication":"Les frais se paient deux fois : 1,5 % + 1,5 % = environ 3 %. En dessous, l’aller-retour est perdant."},{"question":"Une action cote 1 800 FCFA, une autre 30 000 FCFA. Que peut-on en conclure ?","options":["La première est une meilleure affaire","La seconde est de meilleure qualité","Rien : le cours dépend surtout du nombre de titres de la société","La première verse forcément un plus petit dividende"],"correct":2,"explication":"Le cours d’une action ne dit rien de sa qualité ni de sa cherté. Pour juger, il faut rapporter le prix aux bénéfices ou aux dividendes."},{"question":"50 000 FCFA répartis à parts égales sur cinq valeurs. L’une d’elles baisse de 20 %. Combien perd le portefeuille ?","options":["10 000 FCFA","2 000 FCFA","4 000 FCFA","20 000 FCFA"],"correct":1,"explication":"Chaque ligne vaut 10 000 FCFA ; 20 % de 10 000 = 2 000 FCFA, soit 4 % du portefeuille. Sur une seule valeur, la perte aurait été de 10 000 FCFA."},{"question":"Pourquoi éviter de multiplier les très petits ordres ?","options":["La BRVM les refuse","Le minimum de frais par ordre les rend très coûteux","Ils ne donnent pas droit au dividende","Ils sont exécutés en dernier"],"correct":1,"explication":"Beaucoup de SGI appliquent un montant minimum de frais par ordre : sur un petit achat, ce minimum pèse lourd en pourcentage."}],"qcm":{"question":"Une action cote 2 500 FCFA. Vous en achetez 10, avec 1 % de frais. Combien payez-vous ?","options":["2 525 FCFA","25 000 FCFA","25 250 FCFA","27 500 FCFA"],"correct":2,"explication":"10 × 2 500 = 25 000 FCFA, plus 1 % de frais, soit 250 FCFA : 25 250 FCFA au total."},"liens":[{"label":"Simuler un budget d’épargne","href":"/simulateur-budget"},{"label":"Comparer les frais des SGI","href":"/comparateur-sgi"},{"label":"Les cours de toutes les actions","href":"/actions"}]}$wb$::jsonb),
       updated_at = now()
 where slug = 'academy-niveau-1-initiation'
   and content->'lessons'->2->>'titre' = $wb$Combien faut-il pour investir à la BRVM ?$wb$;

update public.academy_courses
   set content = jsonb_set(content, '{lessons,3}', ((content->'lessons'->3) - 'image') || $wb${"titre":"Leçon 4 — Les 3 façons de gagner à la BRVM","categorie":"income","duree_min":9,"sous_titre":"Le dividende, la plus-value et les droits de souscription : trois sources de gain, trois logiques.","resume":"Une action peut rapporter de trois façons : par le dividende versé chaque année, par la plus-value à la revente, et par les droits reçus lors d’une augmentation de capital.\nCette leçon apprend à les calculer, à les additionner, et à reconnaître ce qui n’est pas la norme.","avertissement":"Ceci n’est pas un conseil en investissement. Les dividendes ne sont pas garantis et les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Trois sources de gain","contenu":"Un actionnaire gagne de l’argent de trois manières, qui peuvent s’additionner.","points":[{"titre":"Le dividende","detail":"La part du bénéfice que l’assemblée générale décide de verser chaque année. Un revenu, sans vendre vos titres, mais jamais garanti."},{"titre":"La plus-value","detail":"La différence entre le prix de revente et le prix d’achat. Elle peut aussi être négative : c’est alors une moins-value."},{"titre":"Les droits préférentiels de souscription (DPS)","detail":"Lors d’une augmentation de capital, les actionnaires reçoivent des droits pour souscrire aux nouvelles actions. Ces droits ont une valeur et se négocient."}]},{"type":"importance","titre":"Les calculer","contenu":"Trois formules suffisent. Les exemples sont pédagogiques : ils ne décrivent aucune société cotée.","formules":[{"nom":"Revenu du dividende","expression":"Nombre d’actions × Dividende par action","exemple":"300 × 1 000 = 300 000 FCFA"},{"nom":"Plus-value","expression":"(Prix de revente − Prix d’achat) × Nombre d’actions","exemple":"(5 600 − 5 000) × 200 = 120 000 FCFA"},{"nom":"Rendement total","expression":"(Dividendes reçus + Plus-value) ÷ Somme investie","exemple":"(80 000 + 120 000) ÷ 1 000 000 = 20 %"}]},{"type":"cas","reel":true,"titre":"Sur la BRVM : la régularité des dividendes","contenu":"Le dividende d’une société varie d’un exercice à l’autre. Le tableau donne le dividende par action de quatre valeurs sur cinq exercices, tel qu’enregistré dans notre base.\nRepérez les distributions régulières, celles qui progressent, et les baisses.","donnees_reelles":{"vue":"historique","codes":["SNTS","ORAC","SGBC","CIEC"]}},{"type":"cas","reel":true,"titre":"Sur la BRVM : ce que rapportent 100 actions","contenu":"Le même calcul, appliqué au dernier dividende enregistré et au cours de la dernière séance. Le rendement change chaque jour avec le cours.","donnees_reelles":{"vue":"rendement","codes":["SNTS","ORAC","SGBC","CIEC"],"actions":100}},{"type":"importance","titre":"Une augmentation de capital : trois choix","contenu":"Quand une société cotée émet de nouvelles actions, ses actionnaires reçoivent des DPS, en proportion des titres qu’ils détiennent. Le prix de souscription est fixé par la société dans la note d’information de l’opération.","points":[{"titre":"Exercer ses droits","detail":"Vous souscrivez aux nouvelles actions et gardez votre part du capital.","verifier":"le prix de souscription et la période de l’opération."},{"titre":"Céder ses droits","detail":"Les DPS se négocient pendant la période de souscription : vous encaissez leur valeur sans rien débourser."},{"titre":"Ne rien faire","detail":"À la fin de la période, les droits non utilisés perdent leur valeur. C’est le seul mauvais choix."}]},{"type":"piege","titre":"Les erreurs à éviter","contenu":"Trois confusions coûtent cher aux débutants.","points":[{"titre":"Prendre une envolée passée pour la norme","detail":"Une action qui a triplé en quelques années est l’exception. Un rendement passé, même réel, ne se répète pas sur commande."},{"titre":"Acheter juste avant le détachement pour « toucher » le dividende","detail":"Au détachement, le cours baisse d’environ le montant du dividende : le gain n’est pas gratuit."},{"titre":"Oublier l’impôt","detail":"Le dividende est versé après une retenue à la source, dont le taux dépend du pays de la société.","verifier":"si le montant affiché est brut ou net."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Quatre idées à garder en tête.","points":[{"titre":"Trois sources de gain","detail":"Dividende, plus-value, droits de souscription."},{"titre":"Le dividende est voté, pas promis","detail":"Il peut baisser ou disparaître d’un exercice à l’autre."},{"titre":"Le rendement total additionne tout","detail":"Dividendes reçus et plus-value, rapportés à la somme investie."},{"titre":"Ne jamais laisser expirer ses DPS","detail":"Les exercer ou les céder, mais ne pas les ignorer."}]}],"chart":null,"charts":[],"quiz":[{"question":"Vous achetez 200 actions à 5 000 FCFA et les revendez à 5 600 FCFA. Quelle est votre plus-value, hors frais ?","options":["600 FCFA","12 000 FCFA","120 000 FCFA","1 120 000 FCFA"],"correct":2,"explication":"(5 600 − 5 000) × 200 = 600 × 200 = 120 000 FCFA."},{"question":"Vous avez investi 1 000 000 FCFA, reçu 80 000 FCFA de dividendes et réalisé 120 000 FCFA de plus-value. Quel est votre rendement total ?","options":["8 %","12 %","20 %","200 %"],"correct":2,"explication":"(80 000 + 120 000) ÷ 1 000 000 = 200 000 ÷ 1 000 000 = 20 %."},{"question":"Une société lance une augmentation de capital. Quel choix fait perdre de l’argent à coup sûr ?","options":["Exercer ses DPS","Céder ses DPS sur le marché","Laisser expirer ses DPS sans rien faire","Céder une partie et exercer l’autre"],"correct":2,"explication":"Les droits non utilisés perdent leur valeur à la fin de la période de souscription. Les exercer ou les céder préserve leur valeur."},{"question":"Vous achetez une action la veille du détachement, juste pour toucher le dividende. Que se passe-t-il ?","options":["Vous gagnez le dividende sans contrepartie","Le cours baisse d’environ le montant du dividende au détachement","Le dividende vous est refusé","La société vous rembourse les frais"],"correct":1,"explication":"Au détachement, le cours est ajusté du dividende. Le gain apparent est compensé, et les frais d’achat restent à votre charge."},{"question":"Une société a versé un dividende chaque année depuis dix ans. Que pouvez-vous en déduire ?","options":["Le dividende est garanti l’an prochain","Il est voté chaque année : il peut baisser ou disparaître","Il augmentera forcément","La société ne peut plus le supprimer"],"correct":1,"explication":"La régularité passée est un bon signe, pas une garantie : l’assemblée générale décide chaque année."}],"qcm":{"question":"Vous achetez 200 actions à 5 000 FCFA et les revendez à 5 600 FCFA. Quelle est votre plus-value, hors frais ?","options":["600 FCFA","12 000 FCFA","120 000 FCFA","1 120 000 FCFA"],"correct":2,"explication":"(5 600 − 5 000) × 200 = 600 × 200 = 120 000 FCFA."},"liens":[{"label":"Les dividendes de toutes les valeurs","href":"/dividendes"},{"label":"Le calendrier des dividendes","href":"/dividendes/calendrier"},{"label":"Le rendement réel, après inflation","href":"/rendement-vrai"}]}$wb$::jsonb),
       updated_at = now()
 where slug = 'academy-niveau-1-initiation'
   and content->'lessons'->3->>'titre' = $wb$Les 3 façons de gagner à la BRVM$wb$;
